-- Блоки «Выбирай X, если…» и FAQ сравнений, пересобраны из проверенных карточек, 2026-10-11.
-- Было / стало: scripts/audit/comparisons_2026-10-11_review.json. Идемпотентно.

-- fiscal-ai-vs-koyfin
UPDATE comparisons SET choose_a = $c$["✅ You want AI to analyze earnings call transcripts and surface management tone and key statements automatically", "✅ You need natural language financial queries that generate charts and summaries directly from the data", "✅ You research companies with deep KPI needs and want access to segment-level data for 2,500+ companies", "✅ You're a platform or institution that wants to pipe financial data into your own AI tools via MCP or API"]$c$, choose_b = $c$["✅ You want a usable free plan with real financials, charting, watchlists, and screens before paying anything", "✅ You need to screen thousands of securities using 5,900+ fundamental, technical, and macro criteria", "✅ You want fully customizable, Bloomberg-style dashboards for market and macro monitoring", "✅ You're a financial advisor who needs dedicated Advisor Core or Advisor Pro tiers with client-facing tools"]$c$, faq = $c$[{"q": "What is Fiscal.ai?", "a": "Fiscal.ai, formerly FinChat.io, is an AI-powered financial research platform covering 100,000+ public companies, ETFs, and funds, combining structured financials with AI analysis of earnings transcripts and natural language queries. It also offers MCP and API data feeds for institutions."}, {"q": "What is Koyfin?", "a": "Koyfin is a financial data and analytics platform positioned as an affordable Bloomberg Terminal alternative, offering market data, fundamentals, earnings transcripts, economic indicators, and screening tools with over 5,900 filter criteria."}, {"q": "Is Koyfin free?", "a": "Yes, Koyfin has a Free plan with 2 years of financials, 1 year of estimates, advanced charting, 2 watchlists, and 2 screens. Paid plans start at $39/month for Plus and go up to $299/month for Advisor Pro."}, {"q": "Does Fiscal.ai have a free plan?", "a": "No, Fiscal.ai has no free plan — only a 7-day trial that requires a credit card and auto-converts to a paid subscription starting at $49/month."}, {"q": "Which is better for screening and comparing many stocks at once?", "a": "Koyfin is better suited for this, with 5,900+ screening criteria and customizable comparison dashboards built for scanning large numbers of securities. Fiscal.ai is more focused on deep AI-assisted analysis of individual companies' financials and transcripts."}, {"q": "Which is better for AI-assisted earnings call analysis?", "a": "Fiscal.ai is purpose-built for this, using AI to analyze transcripts and answer natural language questions about company financials. Koyfin's homepage AI widget only forwards prompts to external chatbots rather than performing in-product analysis."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'en';
UPDATE comparisons SET choose_a = $c$["✅ Quieres que la IA analice transcripciones de conference calls de resultados y detecte automáticamente el tono de la gerencia y declaraciones clave", "✅ Necesitas consultas financieras en lenguaje natural que generen gráficos y resúmenes directamente a partir de los datos", "✅ Investigas empresas con necesidades profundas de KPI y quieres acceso a datos a nivel de segmento para más de 2.500 empresas", "✅ Eres una plataforma o institución que quiere integrar datos financieros en tus propias herramientas de IA mediante MCP o API"]$c$, choose_b = $c$["✅ Quieres un plan gratuito usable con datos financieros reales, gráficos, listas de seguimiento y screeners antes de pagar nada", "✅ Necesitas filtrar miles de valores usando más de 5.900 criterios fundamentales, técnicos y macroeconómicos", "✅ Quieres paneles totalmente personalizables, al estilo Bloomberg, para el monitoreo de mercado y macroeconómico", "✅ Eres un asesor financiero que necesita los niveles dedicados Advisor Core o Advisor Pro con herramientas orientadas al cliente"]$c$, faq = $c$[{"q": "¿Qué es Fiscal.ai?", "a": "Fiscal.ai, antes FinChat.io, es una plataforma de investigación financiera impulsada por IA que cubre más de 100.000 empresas públicas, ETF y fondos, combinando datos financieros estructurados con análisis de IA de transcripciones de resultados y consultas en lenguaje natural. También ofrece feeds de datos MCP y API para instituciones."}, {"q": "¿Qué es Koyfin?", "a": "Koyfin es una plataforma de datos y análisis financiero posicionada como una alternativa asequible a Bloomberg Terminal, que ofrece datos de mercado, datos fundamentales, transcripciones de resultados, indicadores económicos y herramientas de screening con más de 5.900 criterios de filtrado."}, {"q": "¿Es gratuito Koyfin?", "a": "Sí, Koyfin tiene un plan Free con 2 años de datos financieros, 1 año de estimaciones, gráficos avanzados, 2 listas de seguimiento y 2 screeners. Los planes pagos comienzan en $39/mes para Plus y llegan hasta $299/mes para Advisor Pro."}, {"q": "¿Tiene Fiscal.ai un plan gratuito?", "a": "No, Fiscal.ai no tiene plan gratuito — solo una prueba de 7 días que requiere tarjeta de crédito y se convierte automáticamente en una suscripción paga que comienza en $49/mes."}, {"q": "¿Cuál es mejor para filtrar y comparar muchas acciones a la vez?", "a": "Koyfin es más adecuado para esto, con más de 5.900 criterios de screening y paneles de comparación personalizables diseñados para examinar grandes cantidades de valores. Fiscal.ai está más enfocado en el análisis profundo asistido por IA de los datos financieros y transcripciones de empresas individuales."}, {"q": "¿Cuál es mejor para el análisis asistido por IA de conference calls de resultados?", "a": "Fiscal.ai está diseñado específicamente para esto, usando IA para analizar transcripciones y responder preguntas en lenguaje natural sobre los datos financieros de las empresas. El widget de IA de la página principal de Koyfin solo reenvía las consultas a chatbots externos en lugar de realizar un análisis dentro del producto."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'es';
UPDATE comparisons SET choose_a = $c$["✅ Sie möchten, dass KI Earnings-Call-Transkripte analysiert und automatisch Management-Tonalität sowie wichtige Aussagen herausarbeitet", "✅ Sie benötigen natürlichsprachige Finanzabfragen, die direkt aus den Daten Diagramme und Zusammenfassungen erstellen", "✅ Sie recherchieren Unternehmen mit umfangreichem KPI-Bedarf und wünschen Zugang zu Segmentdaten für über 2.500 Unternehmen", "✅ Sie sind eine Plattform oder Institution, die Finanzdaten über MCP oder API in eigene KI-Tools einspeisen möchte"]$c$, choose_b = $c$["✅ Sie möchten einen nutzbaren kostenlosen Plan mit echten Finanzdaten, Charting, Watchlists und Screens, bevor Sie etwas bezahlen", "✅ Sie müssen Tausende Wertpapiere anhand von über 5.900 fundamentalen, technischen und makroökonomischen Kriterien screenen", "✅ Sie wünschen voll anpassbare, Bloomberg-ähnliche Dashboards für Markt- und Makro-Monitoring", "✅ Sie sind Finanzberater und benötigen dedizierte Advisor-Core- oder Advisor-Pro-Tarife mit kundenorientierten Tools"]$c$, faq = $c$[{"q": "Was ist Fiscal.ai?", "a": "Fiscal.ai, früher FinChat.io, ist eine KI-gestützte Finanzrecherche-Plattform, die über 100.000 börsennotierte Unternehmen, ETFs und Fonds abdeckt und strukturierte Finanzdaten mit KI-Analyse von Earnings-Transkripten und natürlichsprachigen Abfragen kombiniert. Zudem bietet sie MCP- und API-Datenfeeds für Institutionen."}, {"q": "Was ist Koyfin?", "a": "Koyfin ist eine Finanzdaten- und Analyseplattform, die als erschwingliche Alternative zum Bloomberg Terminal positioniert ist und Marktdaten, Fundamentaldaten, Earnings-Transkripte, Wirtschaftsindikatoren sowie Screening-Tools mit über 5.900 Filterkriterien bietet."}, {"q": "Ist Koyfin kostenlos?", "a": "Ja, Koyfin bietet einen kostenlosen Plan mit 2 Jahren Finanzdaten, 1 Jahr Schätzungen, erweitertem Charting, 2 Watchlists und 2 Screens. Kostenpflichtige Pläne beginnen bei 39 $/Monat für Plus und gehen bis zu 299 $/Monat für Advisor Pro."}, {"q": "Bietet Fiscal.ai einen kostenlosen Plan?", "a": "Nein, Fiscal.ai hat keinen kostenlosen Plan — nur eine 7-tägige Testversion, die eine Kreditkarte erfordert und automatisch in ein kostenpflichtiges Abonnement ab 49 $/Monat übergeht."}, {"q": "Was eignet sich besser zum Screenen und Vergleichen vieler Aktien gleichzeitig?", "a": "Koyfin ist hierfür besser geeignet, mit über 5.900 Screening-Kriterien und anpassbaren Vergleichs-Dashboards, die für das Scannen großer Mengen an Wertpapieren konzipiert sind. Fiscal.ai konzentriert sich stärker auf die tiefgehende KI-gestützte Analyse der Finanzdaten und Transkripte einzelner Unternehmen."}, {"q": "Was eignet sich besser für KI-gestützte Analyse von Earnings Calls?", "a": "Fiscal.ai ist genau dafür entwickelt worden und nutzt KI, um Transkripte zu analysieren und natürlichsprachige Fragen zu den Finanzdaten von Unternehmen zu beantworten. Das KI-Widget auf der Koyfin-Startseite leitet Eingaben lediglich an externe Chatbots weiter, anstatt eine Analyse innerhalb des Produkts durchzuführen."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'de';
UPDATE comparisons SET choose_a = $c$["✅ Вы хотите, чтобы ИИ анализировал стенограммы звонков по отчетности и автоматически выявлял тональность руководства и ключевые заявления", "✅ Вам нужны финансовые запросы на естественном языке, которые генерируют графики и сводки прямо на основе данных", "✅ Вы исследуете компании с глубокими потребностями в KPI и хотите получить доступ к данным сегментов для 2 500+ компаний", "✅ Вы платформа или учреждение, которое хочет передавать финансовые данные в собственные ИИ-инструменты через MCP или API"]$c$, choose_b = $c$["✅ Вы хотите удобный бесплатный план с реальными финансовыми данными, графиками, списками наблюдения и скринерами, прежде чем платить что-либо", "✅ Вам нужно отбирать тысячи ценных бумаг, используя 5 900+ фундаментальных, технических и макроэкономических критериев", "✅ Вы хотите полностью настраиваемые дашборды в стиле Bloomberg для мониторинга рынка и макроэкономики", "✅ Вы финансовый консультант, которому нужны специализированные уровни Advisor Core или Advisor Pro с инструментами для работы с клиентами"]$c$, faq = $c$[{"q": "Что такое Fiscal.ai?", "a": "Fiscal.ai, ранее известный как FinChat.io, — это платформа финансовых исследований на основе ИИ, охватывающая 100 000+ публичных компаний, ETF и фондов, сочетающая структурированные финансовые данные с ИИ-анализом стенограмм отчетности и запросами на естественном языке. Также предлагает каналы данных MCP и API для учреждений."}, {"q": "Что такое Koyfin?", "a": "Koyfin — это платформа финансовых данных и аналитики, позиционируемая как доступная альтернатива Bloomberg Terminal, предлагающая рыночные данные, фундаментальные показатели, стенограммы отчетности, экономические индикаторы и инструменты скрининга с более чем 5 900 критериями фильтрации."}, {"q": "Koyfin бесплатный?", "a": "Да, у Koyfin есть бесплатный план с 2 годами финансовых данных, 1 годом прогнозов, продвинутыми графиками, 2 списками наблюдения и 2 скринерами. Платные планы начинаются от $39/месяц для Plus и доходят до $299/месяц для Advisor Pro."}, {"q": "Есть ли у Fiscal.ai бесплатный план?", "a": "Нет, у Fiscal.ai нет бесплатного плана — только 7-дневная пробная версия, которая требует банковской карты и автоматически переходит в платную подписку от $49/месяц."}, {"q": "Что лучше подходит для скрининга и сравнения множества акций одновременно?", "a": "Koyfin лучше подходит для этого, предлагая 5 900+ критериев скрининга и настраиваемые дашборды сравнения, созданные для анализа большого количества ценных бумаг. Fiscal.ai больше сосредоточен на глубоком ИИ-анализе финансовых данных и стенограмм отдельных компаний."}, {"q": "Что лучше подходит для ИИ-анализа звонков по отчетности?", "a": "Fiscal.ai специально создан для этого, используя ИИ для анализа стенограмм и ответов на вопросы на естественном языке о финансовых показателях компаний. ИИ-виджет на главной странице Koyfin лишь пересылает запросы во внешние чат-боты, а не выполняет анализ внутри продукта."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'ru';
UPDATE comparisons SET choose_a = $c$["✅ Ви хочете, щоб ШІ аналізував стенограми дзвінків щодо прибутків і автоматично виявляв тон керівництва та ключові заяви", "✅ Вам потрібні фінансові запити природною мовою, які генерують графіки та підсумки безпосередньо з даних", "✅ Ви досліджуєте компанії з глибокими потребами в KPI і хочете мати доступ до сегментних даних для 2500+ компаній", "✅ Ви платформа або установа, яка хоче передавати фінансові дані у власні AI-інструменти через MCP або API"]$c$, choose_b = $c$["✅ Ви хочете зручний безкоштовний план з реальними фінансовими даними, побудовою графіків, списками спостереження та скринерами, перш ніж щось платити", "✅ Вам потрібно відбирати тисячі цінних паперів за допомогою 5900+ фундаментальних, технічних і макроекономічних критеріїв", "✅ Ви хочете повністю налаштовувані, у стилі Bloomberg, дашборди для моніторингу ринку та макроекономіки", "✅ Ви фінансовий радник, якому потрібні спеціальні рівні Advisor Core або Advisor Pro з інструментами для роботи з клієнтами"]$c$, faq = $c$[{"q": "Що таке Fiscal.ai?", "a": "Fiscal.ai, раніше відомий як FinChat.io, — це фінансова дослідницька платформа на базі ШІ, яка охоплює понад 100 000 публічних компаній, ETF та фондів, поєднуючи структуровані фінансові дані з AI-аналізом стенограм прибутків і запитами природною мовою. Вона також пропонує канали даних MCP та API для установ."}, {"q": "Що таке Koyfin?", "a": "Koyfin — це платформа фінансових даних та аналітики, яка позиціонується як доступна альтернатива Bloomberg Terminal, пропонуючи ринкові дані, фундаментальні показники, стенограми дзвінків щодо прибутків, економічні індикатори та інструменти скринінгу з понад 5900 критеріями фільтрації."}, {"q": "Чи є Koyfin безкоштовним?", "a": "Так, Koyfin має безкоштовний план з 2 роками фінансових даних, 1 роком прогнозів, розширеною побудовою графіків, 2 списками спостереження та 2 скринерами. Платні плани починаються від $39/місяць для Plus і сягають $299/місяць для Advisor Pro."}, {"q": "Чи має Fiscal.ai безкоштовний план?", "a": "Ні, Fiscal.ai не має безкоштовного плану — лише 7-денну пробну версію, яка вимагає кредитну картку і автоматично переходить у платну підписку від $49/місяць."}, {"q": "Що краще для скринінгу та порівняння великої кількості акцій одночасно?", "a": "Koyfin більше підходить для цього, маючи понад 5900 критеріїв скринінгу та налаштовувані дашборди порівняння, створені для сканування великої кількості цінних паперів. Fiscal.ai більше зосереджений на глибокому AI-аналізі фінансових даних і стенограм окремих компаній."}, {"q": "Що краще для AI-аналізу дзвінків щодо прибутків?", "a": "Fiscal.ai спеціально створений для цього, використовуючи ШІ для аналізу стенограм і відповідей на запити природною мовою про фінанси компаній. AI-віджет на головній сторінці Koyfin лише переадресовує запити до зовнішніх чат-ботів, а не виконує аналіз у продукті."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'ua';
UPDATE comparisons SET choose_a = $c$["✅ אתה רוצה ש-AI ינתח תמלילי שיחות ועדכוני רווחים (earnings calls) ויחשוף באופן אוטומטי את הטון ההנהלתי והאמירות המרכזיות", "✅ אתה צריך שאילתות פיננסיות בשפה טבעית שמייצרות גרפים וסיכומים ישירות מהנתונים", "✅ אתה חוקר חברות עם צרכי KPI מעמיקים ורוצה גישה לנתוני סגמנטים ברמת פירוט עבור 2,500+ חברות", "✅ אתה פלטפורמה או מוסד שרוצה להזרים נתונים פיננסיים לכלי AI משלך דרך MCP או API"]$c$, choose_b = $c$["✅ אתה רוצה תוכנית חינמית שימושית עם נתונים פיננסיים אמיתיים, תרשימים, רשימות מעקב וסינונים לפני שאתה משלם משהו", "✅ אתה צריך לסנן אלפי ניירות ערך באמצעות 5,900+ קריטריונים פונדמנטליים, טכניים ומאקרו-כלכליים", "✅ אתה רוצה לוחות מחוונים (dashboards) בסגנון Bloomberg, הניתנים להתאמה מלאה, למעקב אחר שוק ומאקרו", "✅ אתה יועץ פיננסי שזקוק לרמות Advisor Core או Advisor Pro ייעודיות עם כלים הפונים ללקוחות"]$c$, faq = $c$[{"q": "מהו Fiscal.ai?", "a": "Fiscal.ai, שנקרא בעבר FinChat.io, הוא פלטפורמת מחקר פיננסי מבוססת AI המכסה 100,000+ חברות ציבוריות, קרנות ETF וקרנות, ומשלבת נתונים פיננסיים מובנים עם ניתוח AI של תמלילי שיחות רווחים ושאילתות בשפה טבעית. היא גם מציעה הזנות נתונים (data feeds) דרך MCP ו-API עבור מוסדות."}, {"q": "מהו Koyfin?", "a": "Koyfin הוא פלטפורמת נתונים ואנליטיקה פיננסית הממוצבת כחלופה משתלמת ל-Bloomberg Terminal, ומציעה נתוני שוק, נתונים פונדמנטליים, תמלילי שיחות רווחים, מדדים כלכליים וכלי סינון עם למעלה מ-5,900 קריטריוני סינון."}, {"q": "האם Koyfin חינמי?", "a": "כן, ל-Koyfin יש תוכנית חינמית (Free) עם נתונים פיננסיים ל-2 שנים, אומדנים לשנה אחת, תרשימים מתקדמים, 2 רשימות מעקב ו-2 סינונים. התוכניות בתשלום מתחילות ב-$39/חודש עבור Plus ומגיעות עד $299/חודש עבור Advisor Pro."}, {"q": "האם ל-Fiscal.ai יש תוכנית חינמית?", "a": "לא, ל-Fiscal.ai אין תוכנית חינמית — רק תקופת ניסיון (trial) של 7 ימים שדורשת כרטיס אשראי וממירה אוטומטית למנוי בתשלום, החל מ-$49/חודש."}, {"q": "מי עדיף לסינון והשוואה של מניות רבות בבת אחת?", "a": "Koyfin מתאים יותר למטרה זו, עם 5,900+ קריטריוני סינון ולוחות השוואה הניתנים להתאמה אישית, שנבנו לסריקת מספר רב של ניירות ערך. Fiscal.ai מתמקד יותר בניתוח מעמיק בעזרת AI של הנתונים הפיננסיים והתמלילים של חברות בודדות."}, {"q": "מי עדיף לניתוח שיחות רווחים בעזרת AI?", "a": "Fiscal.ai נבנה במיוחד למטרה זו, תוך שימוש ב-AI לניתוח תמלילים ומענה על שאלות בשפה טבעית לגבי הנתונים הפיננסיים של חברות. ווידג'ט ה-AI בדף הבית של Koyfin רק מעביר (forward) בקשות לצ'אטבוטים חיצוניים, במקום לבצע ניתוח בתוך המוצר עצמו."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'he';
UPDATE comparisons SET choose_a = $c$["✅ Vous voulez que l'IA analyse les transcriptions des earnings calls et fasse ressortir automatiquement le ton de la direction et les déclarations clés", "✅ Vous avez besoin de requêtes financières en langage naturel qui génèrent des graphiques et des résumés directement à partir des données", "✅ Vous étudiez des entreprises avec des besoins approfondis en KPI et voulez accéder à des données au niveau des segments pour plus de 2 500 entreprises", "✅ Vous êtes une plateforme ou une institution qui souhaite transmettre des données financières vers vos propres outils d'IA via MCP ou API"]$c$, choose_b = $c$["✅ Vous voulez un plan gratuit utilisable avec de vraies données financières, des graphiques, des watchlists et des filtres avant de payer quoi que ce soit", "✅ Vous avez besoin de filtrer des milliers de titres à l'aide de plus de 5 900 critères fondamentaux, techniques et macroéconomiques", "✅ Vous voulez des tableaux de bord entièrement personnalisables, de style Bloomberg, pour le suivi des marchés et de la macroéconomie", "✅ Vous êtes un conseiller financier qui a besoin des formules dédiées Advisor Core ou Advisor Pro avec des outils destinés aux clients"]$c$, faq = $c$[{"q": "Qu'est-ce que Fiscal.ai ?", "a": "Fiscal.ai, anciennement FinChat.io, est une plateforme de recherche financière alimentée par l'IA couvrant plus de 100 000 entreprises cotées, ETF et fonds, combinant des données financières structurées avec une analyse par IA des transcriptions d'earnings calls et des requêtes en langage naturel. Elle propose également des flux de données MCP et API pour les institutions."}, {"q": "Qu'est-ce que Koyfin ?", "a": "Koyfin est une plateforme de données financières et d'analyse positionnée comme une alternative abordable au Bloomberg Terminal, offrant des données de marché, des données fondamentales, des transcriptions d'earnings calls, des indicateurs économiques et des outils de filtrage avec plus de 5 900 critères."}, {"q": "Koyfin est-il gratuit ?", "a": "Oui, Koyfin propose un plan Free avec 2 ans de données financières, 1 an d'estimations, des graphiques avancés, 2 watchlists et 2 filtres. Les plans payants commencent à 39 $/mois pour Plus et vont jusqu'à 299 $/mois pour Advisor Pro."}, {"q": "Fiscal.ai propose-t-il un plan gratuit ?", "a": "Non, Fiscal.ai n'a pas de plan gratuit — seulement un essai de 7 jours qui nécessite une carte de crédit et se convertit automatiquement en abonnement payant à partir de 49 $/mois."}, {"q": "Lequel est le mieux pour filtrer et comparer de nombreuses actions à la fois ?", "a": "Koyfin est mieux adapté pour cela, avec plus de 5 900 critères de filtrage et des tableaux de bord de comparaison personnalisables conçus pour analyser un grand nombre de titres. Fiscal.ai est davantage axé sur l'analyse approfondie assistée par IA des données financières et des transcriptions d'entreprises individuelles."}, {"q": "Lequel est le mieux pour l'analyse des earnings calls assistée par IA ?", "a": "Fiscal.ai est spécialement conçu pour cela, utilisant l'IA pour analyser les transcriptions et répondre à des questions en langage naturel sur les données financières des entreprises. Le widget IA de la page d'accueil de Koyfin se contente de transmettre les requêtes à des chatbots externes plutôt que d'effectuer une analyse intégrée au produit."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'fr';
UPDATE comparisons SET choose_a = $c$["✅ Você quer que a IA analise transcrições de teleconferências de resultados e destaque automaticamente o tom da gestão e declarações-chave", "✅ Você precisa de consultas financeiras em linguagem natural que gerem gráficos e resumos diretamente a partir dos dados", "✅ Você pesquisa empresas com necessidades profundas de KPIs e quer acesso a dados por segmento de mais de 2.500 empresas", "✅ Você é uma plataforma ou instituição que quer integrar dados financeiros às suas próprias ferramentas de IA via MCP ou API"]$c$, choose_b = $c$["✅ Você quer um plano gratuito utilizável com dados financeiros reais, gráficos, listas de observação e screenings antes de pagar qualquer coisa", "✅ Você precisa fazer screening de milhares de ativos usando mais de 5.900 critérios fundamentalistas, técnicos e macroeconômicos", "✅ Você quer painéis totalmente personalizáveis, no estilo Bloomberg, para monitoramento de mercado e macroeconômico", "✅ Você é um consultor financeiro que precisa de planos dedicados Advisor Core ou Advisor Pro com ferramentas voltadas para clientes"]$c$, faq = $c$[{"q": "O que é o Fiscal.ai?", "a": "O Fiscal.ai, antigo FinChat.io, é uma plataforma de pesquisa financeira baseada em IA que cobre mais de 100.000 empresas de capital aberto, ETFs e fundos, combinando dados financeiros estruturados com análise por IA de transcrições de resultados e consultas em linguagem natural. Também oferece feeds de dados via MCP e API para instituições."}, {"q": "O que é o Koyfin?", "a": "O Koyfin é uma plataforma de dados e análises financeiras posicionada como uma alternativa acessível ao Bloomberg Terminal, oferecendo dados de mercado, fundamentos, transcrições de resultados, indicadores econômicos e ferramentas de screening com mais de 5.900 critérios de filtro."}, {"q": "O Koyfin é gratuito?", "a": "Sim, o Koyfin tem um plano gratuito com 2 anos de dados financeiros, 1 ano de estimativas, gráficos avançados, 2 listas de observação e 2 screenings. Os planos pagos começam em $39/mês no Plus e chegam a $299/mês no Advisor Pro."}, {"q": "O Fiscal.ai tem plano gratuito?", "a": "Não, o Fiscal.ai não tem plano gratuito — apenas um teste de 7 dias que exige cartão de crédito e se converte automaticamente em uma assinatura paga a partir de $49/mês."}, {"q": "Qual é melhor para fazer screening e comparar muitas ações ao mesmo tempo?", "a": "O Koyfin é mais adequado para isso, com mais de 5.900 critérios de screening e painéis de comparação personalizáveis criados para analisar um grande número de ativos. O Fiscal.ai é mais focado em análises profundas assistidas por IA dos dados financeiros e transcrições de empresas individuais."}, {"q": "Qual é melhor para análise de teleconferências de resultados assistida por IA?", "a": "O Fiscal.ai foi criado especificamente para isso, usando IA para analisar transcrições e responder perguntas em linguagem natural sobre os dados financeiros das empresas. O widget de IA na página inicial do Koyfin apenas encaminha os prompts para chatbots externos, em vez de realizar análises dentro do próprio produto."}]$c$::jsonb
 WHERE slug = 'fiscal-ai-vs-koyfin' AND lang = 'pt';

-- tradingview-vs-fiscal-ai
UPDATE comparisons SET choose_a = $c$["✅ You rely on charts, indicators, and price patterns to make trading decisions across stocks, crypto, or forex", "✅ You trade actively and need real-time charting, price alerts, and multi-timeframe analysis", "✅ You want to build or backtest custom indicators using Pine Script", "✅ You want to connect your broker account and place trades directly from the charting platform"]$c$, choose_b = $c$["✅ You research companies fundamentally and want AI to analyze earnings call transcripts for you", "✅ You want to ask natural-language questions about a company's financials and get charts generated automatically", "✅ You need to compare a company against industry peers using structured financial and KPI data", "✅ You're building a platform or internal tool and want to pipe financial data into your own AI workflows via API or MCP"]$c$, faq = $c$[{"q": "What is the difference between TradingView and Fiscal.ai?", "a": "TradingView is a charting and technical analysis platform used for stocks, crypto, forex, and other assets, while Fiscal.ai is an AI-powered fundamental research platform focused on company financials, KPIs, and earnings transcripts. Traders who read price charts tend to use TradingView; investors analyzing company fundamentals tend to use Fiscal.ai."}, {"q": "Which is better for active trading with real-time charts and alerts?", "a": "TradingView is built for this, offering multi-timeframe and multi-symbol charts, price alerts, a large community indicator library, and broker connections for direct trading. Fiscal.ai does not offer charting or trade execution tools."}, {"q": "Is TradingView free?", "a": "TradingView offers a free Basic plan, though it's limited to one chart per tab, two indicators per chart, and three price alerts. Paid tiers start at $14.95/month billed monthly (or $12.95/month billed annually) and add more indicators, alerts, and AI screener requests."}, {"q": "What is Fiscal.ai (formerly FinChat)?", "a": "Fiscal.ai, rebranded from FinChat.io in 2025, is an AI financial research platform covering 100,000+ public companies, ETFs, and funds, with deeper KPI data for 2,500+ companies. It lets users ask natural-language questions about financials and earnings transcripts and get AI-generated summaries and charts in response."}, {"q": "Which is better for researching a company's earnings calls and financial statements?", "a": "Fiscal.ai is purpose-built for this, with AI analysis of earnings transcripts, financial statements, and KPIs, plus natural language queries that generate charts and summaries. TradingView focuses on price charting rather than document-based fundamental research."}, {"q": "Does either tool have a free plan?", "a": "TradingView has a free Basic plan with no credit card required, though it's quite limited. Fiscal.ai has no free plan, only a 7-day trial that requires a credit card and auto-converts to a paid subscription."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'en';
UPDATE comparisons SET choose_a = $c$["✅ Confías en gráficos, indicadores y patrones de precios para tomar decisiones de trading en acciones, cripto o forex", "✅ Operas activamente y necesitas gráficos en tiempo real, alertas de precio y análisis en múltiples marcos temporales", "✅ Quieres crear o realizar backtesting de indicadores personalizados usando Pine Script", "✅ Quieres conectar tu cuenta de broker y realizar operaciones directamente desde la plataforma de gráficos"]$c$, choose_b = $c$["✅ Investigas empresas de forma fundamental y quieres que la IA analice las transcripciones de las llamadas de resultados por ti", "✅ Quieres hacer preguntas en lenguaje natural sobre las finanzas de una empresa y obtener gráficos generados automáticamente", "✅ Necesitas comparar una empresa con sus competidores del sector usando datos financieros y de KPI estructurados", "✅ Estás construyendo una plataforma o herramienta interna y quieres integrar datos financieros en tus propios flujos de IA mediante API o MCP"]$c$, faq = $c$[{"q": "¿Cuál es la diferencia entre TradingView y Fiscal.ai?", "a": "TradingView es una plataforma de gráficos y análisis técnico utilizada para acciones, cripto, forex y otros activos, mientras que Fiscal.ai es una plataforma de investigación fundamental impulsada por IA enfocada en las finanzas de empresas, KPIs y transcripciones de resultados. Los traders que analizan gráficos de precios suelen usar TradingView; los inversores que analizan fundamentos de empresas suelen usar Fiscal.ai."}, {"q": "¿Cuál es mejor para el trading activo con gráficos y alertas en tiempo real?", "a": "TradingView está diseñado para esto, ofreciendo gráficos en múltiples marcos temporales y símbolos, alertas de precio, una amplia biblioteca de indicadores de la comunidad y conexiones con brokers para operar directamente. Fiscal.ai no ofrece herramientas de gráficos ni de ejecución de operaciones."}, {"q": "¿Es gratis TradingView?", "a": "TradingView ofrece un plan Basic gratuito, aunque está limitado a un gráfico por pestaña, dos indicadores por gráfico y tres alertas de precio. Los planes de pago comienzan en $14.95/mes facturado mensualmente (o $12.95/mes facturado anualmente) y añaden más indicadores, alertas y solicitudes al screener de IA."}, {"q": "¿Qué es Fiscal.ai (antes FinChat)?", "a": "Fiscal.ai, renombrada a partir de FinChat.io en 2025, es una plataforma de investigación financiera con IA que cubre más de 100,000 empresas públicas, ETFs y fondos, con datos de KPI más detallados para más de 2,500 empresas. Permite a los usuarios hacer preguntas en lenguaje natural sobre finanzas y transcripciones de resultados, y obtener resúmenes y gráficos generados por IA como respuesta."}, {"q": "¿Cuál es mejor para investigar las llamadas de resultados y los estados financieros de una empresa?", "a": "Fiscal.ai está diseñado específicamente para esto, con análisis de IA de transcripciones de resultados, estados financieros y KPIs, además de consultas en lenguaje natural que generan gráficos y resúmenes. TradingView se enfoca en gráficos de precios en lugar de investigación fundamental basada en documentos."}, {"q": "¿Alguna de las dos herramientas tiene un plan gratuito?", "a": "TradingView tiene un plan Basic gratuito que no requiere tarjeta de crédito, aunque es bastante limitado. Fiscal.ai no tiene plan gratuito, solo una prueba de 7 días que requiere tarjeta de crédito y se convierte automáticamente en una suscripción de pago."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'es';
UPDATE comparisons SET choose_a = $c$["✅ Du verlässt dich bei Handelsentscheidungen für Aktien, Krypto oder Forex auf Charts, Indikatoren und Preismuster", "✅ Du handelst aktiv und benötigst Echtzeit-Charting, Preisalarme und Multi-Timeframe-Analysen", "✅ Du möchtest mit Pine Script eigene Indikatoren erstellen oder backtesten", "✅ Du möchtest dein Broker-Konto verbinden und direkt von der Charting-Plattform aus Trades platzieren"]$c$, choose_b = $c$["✅ Du recherchierst Unternehmen fundamental und möchtest, dass KI Earnings-Call-Transkripte für dich analysiert", "✅ Du möchtest in natürlicher Sprache Fragen zu den Finanzen eines Unternehmens stellen und automatisch generierte Charts erhalten", "✅ Du musst ein Unternehmen anhand strukturierter Finanz- und KPI-Daten mit Branchenkonkurrenten vergleichen", "✅ Du baust eine Plattform oder ein internes Tool und möchtest Finanzdaten über API oder MCP in deine eigenen KI-Workflows einspeisen"]$c$, faq = $c$[{"q": "Was ist der Unterschied zwischen TradingView und Fiscal.ai?", "a": "TradingView ist eine Charting- und Technische-Analyse-Plattform für Aktien, Krypto, Forex und andere Assets, während Fiscal.ai eine KI-gestützte Plattform für fundamentale Recherche ist, die sich auf Unternehmensfinanzen, KPIs und Earnings-Transkripte konzentriert. Trader, die Kurscharts lesen, nutzen eher TradingView; Investoren, die Unternehmensfundamentaldaten analysieren, nutzen eher Fiscal.ai."}, {"q": "Welches Tool eignet sich besser für aktives Trading mit Echtzeit-Charts und Alarmen?", "a": "TradingView wurde genau dafür entwickelt und bietet Multi-Timeframe- und Multi-Symbol-Charts, Preisalarme, eine große Community-Indikatorenbibliothek sowie Broker-Verbindungen für den direkten Handel. Fiscal.ai bietet weder Charting- noch Handelsausführungstools."}, {"q": "Ist TradingView kostenlos?", "a": "TradingView bietet einen kostenlosen Basic-Plan an, der jedoch auf einen Chart pro Tab, zwei Indikatoren pro Chart und drei Preisalarme begrenzt ist. Kostenpflichtige Stufen beginnen bei $14.95/Monat bei monatlicher Abrechnung (oder $12.95/Monat bei jährlicher Abrechnung) und bieten zusätzliche Indikatoren, Alarme und AI-Screener-Anfragen."}, {"q": "Was ist Fiscal.ai (ehemals FinChat)?", "a": "Fiscal.ai, 2025 von FinChat.io umbenannt, ist eine KI-gestützte Finanzrecherche-Plattform, die über 100.000 börsennotierte Unternehmen, ETFs und Fonds abdeckt, mit tiefergehenden KPI-Daten für über 2.500 Unternehmen. Nutzer können Fragen in natürlicher Sprache zu Finanzen und Earnings-Transkripten stellen und erhalten als Antwort KI-generierte Zusammenfassungen und Charts."}, {"q": "Welches Tool eignet sich besser zur Recherche von Earnings Calls und Finanzberichten eines Unternehmens?", "a": "Fiscal.ai wurde genau dafür entwickelt, mit KI-Analyse von Earnings-Transkripten, Finanzberichten und KPIs sowie Natural-Language-Abfragen, die Charts und Zusammenfassungen generieren. TradingView konzentriert sich auf Kurs-Charting statt auf dokumentenbasierte Fundamentalrecherche."}, {"q": "Haben beide Tools einen kostenlosen Plan?", "a": "TradingView hat einen kostenlosen Basic-Plan ohne erforderliche Kreditkarte, der jedoch ziemlich eingeschränkt ist. Fiscal.ai hat keinen kostenlosen Plan, sondern nur eine 7-tägige Testversion, die eine Kreditkarte erfordert und sich automatisch in ein kostenpflichtiges Abonnement umwandelt."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'de';
UPDATE comparisons SET choose_a = $c$["✅ Вы полагаетесь на графики, индикаторы и ценовые паттерны при принятии торговых решений по акциям, криптовалютам или форексу", "✅ Вы торгуете активно и нуждаетесь в графиках в реальном времени, ценовых алертах и анализе на нескольких таймфреймах", "✅ Вы хотите создавать или тестировать собственные индикаторы с помощью Pine Script", "✅ Вы хотите подключить счёт у брокера и совершать сделки прямо с платформы для построения графиков"]$c$, choose_b = $c$["✅ Вы исследуете компании с точки зрения фундаментального анализа и хотите, чтобы ИИ анализировал стенограммы звонков по доходам за вас", "✅ Вы хотите задавать вопросы о финансах компании на естественном языке и автоматически получать графики", "✅ Вам нужно сравнивать компанию с отраслевыми аналогами, используя структурированные финансовые данные и KPI", "✅ Вы создаёте платформу или внутренний инструмент и хотите передавать финансовые данные в собственные ИИ-воркфлоу через API или MCP"]$c$, faq = $c$[{"q": "В чём разница между TradingView и Fiscal.ai?", "a": "TradingView — это платформа для построения графиков и технического анализа, используемая для акций, криптовалют, форекса и других активов, в то время как Fiscal.ai — это платформа фундаментального анализа на базе ИИ, сфокусированная на финансах компаний, KPI и стенограммах звонков по доходам. Трейдеры, читающие ценовые графики, как правило, используют TradingView; инвесторы, анализирующие фундаментальные показатели компаний, как правило, используют Fiscal.ai."}, {"q": "Что лучше подходит для активной торговли с графиками и алертами в реальном времени?", "a": "TradingView создан именно для этого — предлагает графики на нескольких таймфреймах и по нескольким инструментам, ценовые алерты, большую библиотеку индикаторов от сообщества и подключение к брокерам для прямой торговли. Fiscal.ai не предлагает инструментов для построения графиков или исполнения сделок."}, {"q": "Бесплатен ли TradingView?", "a": "TradingView предлагает бесплатный план Basic, хотя он ограничен одним графиком на вкладку, двумя индикаторами на график и тремя ценовыми алертами. Платные тарифы начинаются от $14.95/месяц при ежемесячной оплате (или $12.95/месяц при ежегодной оплате) и добавляют больше индикаторов, алертов и запросов к ИИ-скринеру."}, {"q": "Что такое Fiscal.ai (ранее FinChat)?", "a": "Fiscal.ai, переименованный из FinChat.io в 2025 году, — это платформа финансового анализа на базе ИИ, охватывающая более 100 000 публичных компаний, ETF и фондов, с более глубокими данными по KPI для свыше 2 500 компаний. Она позволяет пользователям задавать вопросы о финансах и стенограммах звонков по доходам на естественном языке и получать в ответ сгенерированные ИИ сводки и графики."}, {"q": "Что лучше подходит для исследования звонков по доходам компании и финансовой отчётности?", "a": "Fiscal.ai создан именно для этого — с ИИ-анализом стенограмм звонков по доходам, финансовой отчётности и KPI, а также запросами на естественном языке, которые генерируют графики и сводки. TradingView фокусируется на построении ценовых графиков, а не на фундаментальном анализе на основе документов."}, {"q": "Есть ли у какого-либо из инструментов бесплатный план?", "a": "У TradingView есть бесплатный план Basic, не требующий банковской карты, хотя он довольно ограничен. У Fiscal.ai нет бесплатного плана, есть только 7-дневная пробная версия, которая требует банковскую карту и автоматически переходит в платную подписку."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'ru';
UPDATE comparisons SET choose_a = $c$["✅ Ви покладаєтеся на графіки, індикатори та цінові패�ерни для прийняття торгових рішень щодо акцій, криптовалют або форекс", "✅ Ви активно торгуєте і потребуєте графіків у реальному часі, цінових сповіщень та аналізу за кількома часовими рамками", "✅ Ви хочете створювати або тестувати власні індикатори за допомогою Pine Script", "✅ Ви хочете підключити свій брокерський рахунок і здійснювати угоди безпосередньо з платформи для роботи з графіками"]$c$, choose_b = $c$["✅ Ви досліджуєте компанії фундаментально і хочете, щоб ШІ аналізував для вас стенограми дзвінків про прибутки", "✅ Ви хочете ставити запитання природною мовою про фінанси компанії та автоматично отримувати графіки", "✅ Вам потрібно порівняти компанію з галузевими аналогами, використовуючи структуровані фінансові дані та KPI", "✅ Ви створюєте платформу або внутрішній інструмент і хочете передавати фінансові дані у власні робочі процеси ШІ через API або MCP"]$c$, faq = $c$[{"q": "У чому різниця між TradingView та Fiscal.ai?", "a": "TradingView — це платформа для побудови графіків і технічного аналізу, яка використовується для акцій, криптовалют, форекс та інших активів, тоді як Fiscal.ai — це платформа фундаментальних досліджень на основі ШІ, зосереджена на фінансах компаній, KPI та стенограмах дзвінків про прибутки. Трейдери, які читають цінові графіки, зазвичай використовують TradingView; інвестори, які аналізують фундаментальні показники компаній, зазвичай використовують Fiscal.ai."}, {"q": "Що краще для активної торгівлі з графіками та сповіщеннями в реальному часі?", "a": "TradingView створено саме для цього — платформа пропонує графіки за кількома часовими рамками та символами, цінові сповіщення, велику бібліотеку індикаторів від спільноти та підключення до брокерів для прямої торгівлі. Fiscal.ai не пропонує інструментів для побудови графіків чи виконання угод."}, {"q": "Чи TradingView безкоштовний?", "a": "TradingView пропонує безкоштовний план Basic, хоча він обмежений одним графіком на вкладку, двома індикаторами на графік і трьома ціновими сповіщеннями. Платні тарифи починаються від $14.95/місяць при щомісячній оплаті (або $12.95/місяць при річній оплаті) і додають більше індикаторів, сповіщень та запитів до AI-скринера."}, {"q": "Що таке Fiscal.ai (раніше FinChat)?", "a": "Fiscal.ai, перейменований з FinChat.io у 2025 році, — це платформа фінансових досліджень на основі ШІ, яка охоплює понад 100 000 публічних компаній, ETF і фондів, з глибшими даними KPI для понад 2 500 компаній. Вона дозволяє користувачам ставити запитання природною мовою про фінанси та стенограми дзвінків про прибутки й отримувати у відповідь згенеровані ШІ підсумки та графіки."}, {"q": "Що краще для дослідження дзвінків про прибутки компанії та фінансової звітності?", "a": "Fiscal.ai спеціально створено для цього — з ШІ-аналізом стенограм дзвінків про прибутки, фінансової звітності та KPI, а також запитами природною мовою, які генерують графіки та підсумки. TradingView зосереджується на побудові цінових графіків, а не на дослідженні фундаментальних показників на основі документів."}, {"q": "Чи має будь-який із цих інструментів безкоштовний план?", "a": "TradingView має безкоштовний план Basic, який не вимагає кредитної картки, хоча він досить обмежений. Fiscal.ai не має безкоштовного плану, лише 7-денну пробну версію, яка вимагає кредитну картку й автоматично переходить у платну підписку."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'ua';
UPDATE comparisons SET choose_a = $c$["✅ אתם מסתמכים על גרפים, אינדיקטורים ותבניות מחיר כדי לקבל החלטות מסחר במניות, קריפטו או forex", "✅ אתם סוחרים באופן אקטיבי וזקוקים לגרפים בזמן אמת, התראות מחיר וניתוח מולטי-טיים-פריים", "✅ אתם רוצים לבנות או לבצע בקטסט לאינדיקטורים מותאמים אישית באמצעות Pine Script", "✅ אתם רוצים לחבר את חשבון הברוקר שלכם ולבצע עסקאות ישירות מפלטפורמת הגרפים"]$c$, choose_b = $c$["✅ אתם חוקרים חברות מבחינה פונדמנטלית ורוצים ש-AI ינתח עבורכם תמלילי שיחות ועידה לדוחות כספיים", "✅ אתם רוצים לשאול שאלות בשפה טבעית על הנתונים הפיננסיים של חברה ולקבל גרפים שנוצרים אוטומטית", "✅ אתם צריכים להשוות חברה מול מתחרות בענף באמצעות נתונים פיננסיים ו-KPI מובנים", "✅ אתם בונים פלטפורמה או כלי פנימי ורוצים להזרים נתונים פיננסיים לתהליכי עבודה משלכם מבוססי AI דרך API או MCP"]$c$, faq = $c$[{"q": "מה ההבדל בין TradingView ל-Fiscal.ai?", "a": "TradingView היא פלטפורמת גרפים וניתוח טכני המשמשת למניות, קריפטו, forex ונכסים נוספים, בעוד ש-Fiscal.ai היא פלטפורמת מחקר פונדמנטלי מבוססת AI המתמקדת בנתונים פיננסיים של חברות, KPI ותמלילי דוחות כספיים. סוחרים שקוראים גרפי מחיר נוטים להשתמש ב-TradingView; משקיעים שמנתחים יסודות פונדמנטליים של חברות נוטים להשתמש ב-Fiscal.ai."}, {"q": "מה עדיף למסחר אקטיבי עם גרפים בזמן אמת והתראות?", "a": "TradingView נבנתה בדיוק למטרה זו, ומציעה גרפים במספר טיים-פריימים וסימבולים, התראות מחיר, ספריית אינדיקטורים קהילתית גדולה וחיבורים לברוקרים לביצוע מסחר ישיר. Fiscal.ai אינה מציעה כלי גרפים או ביצוע עסקאות."}, {"q": "האם TradingView חינמית?", "a": "TradingView מציעה תוכנית Basic חינמית, אך היא מוגבלת לגרף אחד בכל לשונית, שני אינדיקטורים לגרף ושלוש התראות מחיר. התוכניות בתשלום מתחילות ב-$14.95 לחודש בחיוב חודשי (או $12.95 לחודש בחיוב שנתי) ומוסיפות עוד אינדיקטורים, התראות ובקשות לסורק AI."}, {"q": "מהי Fiscal.ai (לשעבר FinChat)?", "a": "Fiscal.ai, שעברה מיתוג מחדש מ-FinChat.io ב-2025, היא פלטפורמת מחקר פיננסי מבוססת AI המכסה למעלה מ-100,000 חברות ציבוריות, ETF וקרנות, עם נתוני KPI מעמיקים יותר עבור למעלה מ-2,500 חברות. היא מאפשרת למשתמשים לשאול שאלות בשפה טבעית על נתונים פיננסיים ותמלילי דוחות כספיים ולקבל בתגובה סיכומים וגרפים שנוצרים על ידי AI."}, {"q": "מה עדיף לחקירת שיחות ועידה לדוחות כספיים ודוחות כספיים של חברה?", "a": "Fiscal.ai בנויה בדיוק למטרה זו, עם ניתוח AI של תמלילי דוחות כספיים, דוחות כספיים ו-KPI, בנוסף לשאילתות בשפה טבעית שמייצרות גרפים וסיכומים. TradingView מתמקדת בגרפי מחיר ולא במחקר פונדמנטלי מבוסס מסמכים."}, {"q": "האם לאחת מהכלים יש תוכנית חינמית?", "a": "ל-TradingView יש תוכנית Basic חינמית שלא דורשת כרטיס אשראי, אם כי היא מוגבלת למדי. ל-Fiscal.ai אין תוכנית חינמית, רק תקופת ניסיון של 7 ימים שדורשת כרטיס אשראי והופכת אוטומטית למנוי בתשלום."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'he';
UPDATE comparisons SET choose_a = $c$["✅ Vous vous appuyez sur des graphiques, des indicateurs et des figures de prix pour prendre vos décisions de trading sur les actions, les cryptos ou le forex", "✅ Vous tradez activement et avez besoin de graphiques en temps réel, d'alertes de prix et d'analyses multi-temporelles", "✅ Vous souhaitez créer ou backtester des indicateurs personnalisés avec Pine Script", "✅ Vous souhaitez connecter votre compte de courtage et passer des ordres directement depuis la plateforme de graphiques"]$c$, choose_b = $c$["✅ Vous étudiez les entreprises d'un point de vue fondamental et souhaitez que l'IA analyse les transcriptions des appels de résultats pour vous", "✅ Vous souhaitez poser des questions en langage naturel sur les finances d'une entreprise et obtenir des graphiques générés automatiquement", "✅ Vous avez besoin de comparer une entreprise à ses pairs du secteur à l'aide de données financières et de KPI structurées", "✅ Vous développez une plateforme ou un outil interne et souhaitez intégrer des données financières dans vos propres workflows d'IA via API ou MCP"]$c$, faq = $c$[{"q": "Quelle est la différence entre TradingView et Fiscal.ai ?", "a": "TradingView est une plateforme de graphiques et d'analyse technique utilisée pour les actions, les cryptos, le forex et d'autres actifs, tandis que Fiscal.ai est une plateforme de recherche fondamentale alimentée par l'IA, axée sur les finances des entreprises, les KPI et les transcriptions des résultats. Les traders qui lisent des graphiques de prix ont tendance à utiliser TradingView ; les investisseurs qui analysent les fondamentaux des entreprises ont tendance à utiliser Fiscal.ai."}, {"q": "Lequel est le meilleur pour le trading actif avec des graphiques et des alertes en temps réel ?", "a": "TradingView est conçu pour cela, offrant des graphiques multi-temporels et multi-symboles, des alertes de prix, une large bibliothèque d'indicateurs communautaires et des connexions avec les courtiers pour trader directement. Fiscal.ai ne propose pas d'outils de graphiques ni d'exécution d'ordres."}, {"q": "TradingView est-il gratuit ?", "a": "TradingView propose un plan Basic gratuit, bien qu'il soit limité à un graphique par onglet, deux indicateurs par graphique et trois alertes de prix. Les formules payantes commencent à 14,95 $/mois en facturation mensuelle (ou 12,95 $/mois en facturation annuelle) et ajoutent plus d'indicateurs, d'alertes et de requêtes au screener IA."}, {"q": "Qu'est-ce que Fiscal.ai (anciennement FinChat) ?", "a": "Fiscal.ai, renommé depuis FinChat.io en 2025, est une plateforme de recherche financière basée sur l'IA couvrant plus de 100 000 entreprises cotées, ETF et fonds, avec des données de KPI plus approfondies pour plus de 2 500 entreprises. Elle permet aux utilisateurs de poser des questions en langage naturel sur les finances et les transcriptions des résultats et d'obtenir en réponse des résumés et des graphiques générés par l'IA."}, {"q": "Lequel est le meilleur pour étudier les appels de résultats et les états financiers d'une entreprise ?", "a": "Fiscal.ai est spécialement conçu pour cela, avec une analyse par IA des transcriptions des résultats, des états financiers et des KPI, ainsi que des requêtes en langage naturel qui génèrent des graphiques et des résumés. TradingView se concentre sur les graphiques de prix plutôt que sur la recherche fondamentale basée sur des documents."}, {"q": "L'un des deux outils propose-t-il un plan gratuit ?", "a": "TradingView propose un plan Basic gratuit sans carte bancaire requise, bien qu'il soit assez limité. Fiscal.ai n'a pas de plan gratuit, uniquement un essai de 7 jours qui nécessite une carte bancaire et se convertit automatiquement en abonnement payant."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'fr';
UPDATE comparisons SET choose_a = $c$["✅ Você depende de gráficos, indicadores e padrões de preço para tomar decisões de negociação em ações, criptomoedas ou forex", "✅ Você negocia ativamente e precisa de gráficos em tempo real, alertas de preço e análise multi-timeframe", "✅ Você quer construir ou fazer backtest de indicadores personalizados usando Pine Script", "✅ Você quer conectar sua conta de corretora e executar negociações diretamente pela plataforma de gráficos"]$c$, choose_b = $c$["✅ Você pesquisa empresas de forma fundamentalista e quer que a IA analise transcrições de earnings calls para você", "✅ Você quer fazer perguntas em linguagem natural sobre as finanças de uma empresa e obter gráficos gerados automaticamente", "✅ Você precisa comparar uma empresa com seus pares do setor usando dados financeiros e de KPI estruturados", "✅ Você está construindo uma plataforma ou ferramenta interna e quer integrar dados financeiros aos seus próprios fluxos de IA via API ou MCP"]$c$, faq = $c$[{"q": "Qual é a diferença entre TradingView e Fiscal.ai?", "a": "TradingView é uma plataforma de gráficos e análise técnica usada para ações, criptomoedas, forex e outros ativos, enquanto Fiscal.ai é uma plataforma de pesquisa fundamentalista com IA focada em finanças de empresas, KPIs e transcrições de earnings calls. Traders que leem gráficos de preço tendem a usar o TradingView; investidores que analisam fundamentos de empresas tendem a usar o Fiscal.ai."}, {"q": "Qual é melhor para negociação ativa com gráficos e alertas em tempo real?", "a": "O TradingView foi construído para isso, oferecendo gráficos multi-timeframe e multi-símbolo, alertas de preço, uma ampla biblioteca de indicadores da comunidade e conexões com corretoras para negociação direta. O Fiscal.ai não oferece ferramentas de gráficos ou execução de negociações."}, {"q": "O TradingView é gratuito?", "a": "O TradingView oferece um plano Basic gratuito, embora seja limitado a um gráfico por aba, dois indicadores por gráfico e três alertas de preço. Os planos pagos começam em $14.95/mês cobrados mensalmente (ou $12.95/mês cobrados anualmente) e adicionam mais indicadores, alertas e solicitações do AI screener."}, {"q": "O que é o Fiscal.ai (antigo FinChat)?", "a": "O Fiscal.ai, rebatizado do FinChat.io em 2025, é uma plataforma de pesquisa financeira com IA que cobre mais de 100.000 empresas públicas, ETFs e fundos, com dados de KPI mais aprofundados para mais de 2.500 empresas. Ele permite que os usuários façam perguntas em linguagem natural sobre finanças e transcrições de earnings calls e recebam resumos e gráficos gerados por IA em resposta."}, {"q": "Qual é melhor para pesquisar earnings calls e demonstrações financeiras de uma empresa?", "a": "O Fiscal.ai foi criado especificamente para isso, com análise de IA de transcrições de earnings calls, demonstrações financeiras e KPIs, além de consultas em linguagem natural que geram gráficos e resumos. O TradingView se concentra em gráficos de preço em vez de pesquisa fundamentalista baseada em documentos."}, {"q": "Alguma das ferramentas tem um plano gratuito?", "a": "O TradingView tem um plano Basic gratuito que não exige cartão de crédito, embora seja bastante limitado. O Fiscal.ai não tem plano gratuito, apenas um teste de 7 dias que exige cartão de crédito e se converte automaticamente em uma assinatura paga."}]$c$::jsonb
 WHERE slug = 'tradingview-vs-fiscal-ai' AND lang = 'pt';
